#include <shared_mutex>
#include <chrono>
#include <cassert>
#include <type_traits>
#include <utility>

int main() {
    std::shared_timed_mutex mutex;
    mutex.lock();
    mutex.unlock();
    assert(mutex.try_lock());
    mutex.unlock();
    assert(mutex.try_lock_for(std::chrono::milliseconds(10)));
    mutex.unlock();
    assert(mutex.try_lock_until(
        std::chrono::steady_clock::now() + std::chrono::seconds(1)));
    mutex.unlock();
    mutex.lock_shared();
    mutex.unlock_shared();
    assert(mutex.try_lock_shared());
    mutex.unlock_shared();
    assert(mutex.try_lock_shared_for(std::chrono::milliseconds(10)));
    mutex.unlock_shared();
    assert(mutex.try_lock_shared_until(
        std::chrono::steady_clock::now() + std::chrono::seconds(1)));
    mutex.unlock_shared();
    // native_handle is implementation-defined and is not required for shared_mutex.
}
